export function strengthenReading(lessons) {
 lessons.forEach((l,i)=>{
  const [stimulus,...rows]=transferRows[i];
  l.legacyAssessment={practice:l.practice,check:l.check};
  l.assessmentVersion='reading-v2';
  l.check=rows.map(([prompt,correct,d1,d2,why],j)=>({id:`${l.id}.check.${j+1}.transfer-v2`,prompt,stimulus,options:[correct,d1,d2],answer:0,why,concept:`${l.id}.transfer.${transferRefs[i][j].toLowerCase()}`,refs:['3.1.1',transferRefs[i][j]],conceptLabel:({AO1:'Read fresh evidence',AO2:'Explain language and structure',AO4:'Support a judgment'})[transferRefs[i][j]],objective:j===0?'Read and interpret fresh evidence':j===3?'Test and explain a supported response':'Explain a choice in context'}));
  l.practice=l.legacyAssessment.practice.map((q,j)=>({...q,id:q.id+'.transfer-v2',stimulus:l.views[0].content,stimulusLabel:'Practice passage',options:[q.options[q.answer],errors[i][2*j],errors[i][2*j+1]],answer:0,why:q.why+' The passage supports: '+q.options[q.answer]+' Re-read the neighbouring words to test the competing claims.'}));
  l.tasks=l.tasks.map(t=>[t[0],[t[1][t[2]],errors[i][2],errors[i][3]],0,t[3],'Compare the claim with the wording in the passage; '+l.legacyAssessment.practice[1].why]);
  l.refs=[...new Set([...l.refs,...l.check.flatMap(q=>q.refs)])];
  l.sources.push(oakReadingSources[i]);
  l.contextReading.push({label:'Oak learning-point comparator',url:oakReadingSources[i]},{label:'Open Government Licence (OGL)',url:'https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/'});
  l.sourceNote+=' Learning goals compared with Oak National Academy English lessons licensed under Open Government Licence (OGL); all practice passages and questions here are original Crash Course work. OGL: https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/';
  l.transferNote='Updated reading check · a different original passage. Earlier progress is retained separately; this is foundation practice, not a full GCSE paper.';
 });
}

